```ts
// profileCache.ts
const TTL_MS = 60_000;
const cache = new Map<string, { at: number; value: Promise<Profile> }>();

export function getProfileCached(userId: string): Promise<Profile> {
  const hit = cache.get(userId);
  if (hit && Date.now() - hit.at < TTL_MS) return hit.value;

  // Cache the promise, not the result: concurrent misses share one fetch.
  const value = fetchProfile(userId);
  cache.set(userId, { at: Date.now(), value });
  // Don't cache failures.
  value.catch(() => {
    if (cache.get(userId)?.value === value) cache.delete(userId);
  });
  return value;
}

// Call from every profile write path (update, delete, avatar change).
export const invalidateProfile = (userId: string) => cache.delete(userId);

// chisle: unbounded Map, expired entries only replaced on re-request; add max size/LRU if user count is large
```

